// Forwards every winmm export (proxy_stubs.cpp: `jmp [px_table + i*4]`) to the real
// winmm.dll from the system directory.
#include "proxy.hpp"
#include <windows.h>
#include <cstring>
#include "names.h"  // px_names[], PX_COUNT (generated by tools/gen_winmm_proxy.py)

extern "C" void* px_table[PX_COUNT];
void* px_table[PX_COUNT];

namespace proxy {

void load_real_winmm()
{
    char path[MAX_PATH];
    GetSystemDirectoryA(path, sizeof path);
    std::strncat(path, "\\winmm.dll", sizeof path - std::strlen(path) - 1);
    HMODULE real = LoadLibraryA(path);
    for (int i = 0; i < PX_COUNT; i++)
        px_table[i] = real ? reinterpret_cast<void*>(GetProcAddress(real, px_names[i])) : nullptr;
}

}  // namespace proxy
